        SELECT * FROM (

        SELECT id FROM ifj_trigger
        WHERE status = 'WAITING'
        ORDER BY trigger_time ASC, id ASC
       
        ) WHERE ROWNUM <= #{limit}

mapper.update:
UPDATE ifj_trigger
SET status = #{status},
    message = #{message},
    error_code = #{errorCode},
    message_key = #{messageKey},
    message_args = #{messageArgs},
    update_time = CURRENT_TIMESTAMP(3)
WHERE id = #{id}
  AND status = #{expectedStatus}

    
    
        AND EXISTS (
            SELECT 1 FROM ifj_trigger_work_item work_item
            WHERE work_item.trigger_id = ifj_trigger.id
              AND work_item.status = 'CLAIMED'
              AND work_item.claim_token = #{permit.claimToken}
              AND work_item.fence_token = #{permit.fenceToken}
              AND work_item.lease_deadline > CURRENT_TIMESTAMP(3)
        )
    
    
        AND EXISTS (
            SELECT 1 FROM ifj_trigger_work_item work_item
            WHERE work_item.trigger_id = ifj_trigger.id
              AND work_item.status = 'SUSPENDED'
              AND work_item.fence_token = #{permit.fenceToken}
        )

